import React from 'react';
import { connect } from 'react-redux';
import { batchTableHead } from 'variables/general';

import {
  fetchAllBatchsService,
  saveBatchService,
  fetchBatchService,
  updateBatchService,
  deleteBatchService,
  getCurrentBatch,
  fetchSchoolBatchsService,
} from 'actions/admin/batches';
import { fetchBatchCourseService } from 'actions/admin/courses';
import BatchFormModal from './components/BatchFormModal.jsx';
import {
  getGlobalSchoolUtils,
  getGlobalCurrentBatchUtils,
  setGlobalCurrentBatchUtils,
  setGlobalActualCurrentBatchUtils,
  getCurrentYearBatchUtils,
  formResMessage,
} from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import { showToast } from '../../../actions/admin/auth.js';
import MuiTable from '../Common/MuiTable.jsx';
import { ActiveSpan } from '../Common/StatusBadges.jsx';
// import { updateBackdropState } from 'actions/admin/config.js';

class BatchPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      showAlert: false,
      message: '',
      alertType: '',
      confirmModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      formAction: '',
    };
    this.topRef = React.createRef(null);
  }

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (globalSchool?.schoolId) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchAllBatches('init');
        if (batchId && !this.props?.batchCourses.length) {
          this.props.fetchBatchCourse({
            schoolId: this.state.schoolId,
            batchId,
            token: this.props.loggedUserToken,
          });
        }
      });
    } else {
      this.showWarning('Please select school', 'warning');
    }
  }

  fetchAllBatches = actionType => {
    const { batchData, loggedUserId, loggedUserToken } = this.props;
    if (!batchData?.content.length || actionType === 'update') {
      this.props.fetchAllBatches({
        schoolId: this.state.schoolId,
        adminId: loggedUserId,
        token: loggedUserToken,
        pageParams: this.state.pageParams,
      });
    }
  };

  formModalOpen = () => {
    // store.dispatch(updateBackdropState(true));
    this.setState({ isModalOpen: true, formAction: 'ADD' });
  };

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  saveBatch = async data => {
    const globalSchool = getGlobalSchoolUtils();
    const { startYear } = getCurrentYearBatchUtils();
    const { loggedUserId, loggedUserToken } = this.props;
    data.school = { schoolId: this.state.schoolId || globalSchool.schoolId };
    const res = await this.props.saveBatch({
      postData: data,
      adminId: loggedUserId,
      token: loggedUserToken,
    });
    const resBatch = res.data;
    if (resBatch?.batchId && resBatch.startYear === startYear) {
      const bData = {
        batchId: resBatch.batchId,
        startYear: resBatch.startYear,
        endYear: resBatch.endYear,
      };
      setGlobalCurrentBatchUtils(bData);
      setGlobalActualCurrentBatchUtils(bData);
      store.dispatch(getCurrentBatch(resBatch));
    }
  };

  fetchBatch = batchId => {
    return this.props.fetchBatch({ batchId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateBatch = data => {
    return this.props.updateBatch({ batchId: data.batchId, postData: data, token: this.props.loggedUserToken });
  };

  fetchSchoolBatchs = () => {
    const globalSchool = getGlobalSchoolUtils();
    const { loggedUserToken } = this.props;
    const schoolId = globalSchool.schoolId || this.state.schoolId;
    if (schoolId) {
      this.props.fetchSchoolBatchs({
        schoolId,
        token: loggedUserToken,
      });
    }
  };

  batchUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Batch added successfully' : 'Batch Updated successfully', 'success');
    this.fetchAllBatches('update');
    this.fetchSchoolBatchs();
  };

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  deleteBatch = batchId => {
    return this.props
      .deleteBatch({ batchId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchAllBatches('update');
        // if (currentBatchId === batchId || startYear === passStartYear) {
        //   removeLocalStoreItem('currentBatch');
        //   removeLocalStoreItem('actualCurrentBatch');
        // }
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    this.setState(
      {
        pageParams: {
          ...this.state.pageParams,
          page,
        },
      },
      () => {
        // window.scrosllTo(0, this.topRef.current.offsetTop)
        // let wHeight = window.innerHeight;
        // window.scrollY = wHeight;
        this.fetchAllBatches('update');
      }
    );
  };

  render() {
    const { isModalOpen, formAction } = this.state;
    const { batchCourses, batchData, batch } = this.props;
    const { startYear } = getCurrentYearBatchUtils();

    return (
      <div className="content" ref={this.topRef}>
        <MuiTable
          tableHeaders={batchTableHead}
          tableBodyData={{
            ...batchData,
            content: batchData?.content
              ?.sort((a, b) => b.startYear - a.startYear)
              .map(el => ({
                ...el,
                ...(el.startYear === startYear && {
                  name: (
                    <>
                      {`${el.startYear} - ${el.endYear}`}
                      <span className="ml-2">
                        <ActiveSpan status="ACTIVE" />
                      </span>
                    </>
                  ),
                }),
              })),
          }}
          bodyColumns={['name', 'startYear', 'endYear', 'action']}
          dropDownActions={['edit']}
          idName="batchId"
          fetchItem={this.fetchBatch}
          fetchPageData={this.fetchPageData}
        />
        <BatchFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          courses={batchCourses}
          saveBatch={this.saveBatch}
          batch={batch}
          updateBatch={this.updateBatch}
          batchUpdateSuccess={this.batchUpdateSuccess}
          formAction={formAction}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    batchData: state.batches.batchData,
    batch: state.batches.batch,
    batchCourses: state.courses.batchCourseList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchBatchCourse: data => dispatch(fetchBatchCourseService(data)),
    fetchAllBatches: data => dispatch(fetchAllBatchsService(data)),
    saveBatch: data => dispatch(saveBatchService(data)),
    fetchBatch: data => dispatch(fetchBatchService(data)),
    updateBatch: data => dispatch(updateBatchService(data)),
    deleteBatch: data => dispatch(deleteBatchService(data)),

    // Fetch school batches
    fetchSchoolBatchs: data => dispatch(fetchSchoolBatchsService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(BatchPage);
